import React, { useEffect, useRef, useState } from "react";
import "../../src/App.css";
// import Swal from 'sweetalert2';
// import 'sweetalert2/dist/sweetalert2.css';
import moment from "moment";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
// import { IoMdClose } from "react-icons/io";
// import { CiCircleInfo } from "react-icons/ci";
import config from "../axiosService/Config";
import { makeApiRequest } from "../axiosService/ApiCall";
import DataTable from "react-data-table-component";
import { Spinner } from "react-bootstrap";
import { FaCalendarAlt, FaRegCopy } from "react-icons/fa";

import Select from "react-select";
import eth from "../Assets/images/ethereum.png";
import usdt from "../Assets/images/usdt.png";
import btc from "../Assets/images/btc.png";
import sol from "../Assets/images/solana.png";
import ltc from "../Assets/images/litecoin.png";
import car from "../Assets/images/cardano.png";
import { enUS } from "date-fns/locale";
import { DateRange } from "react-date-range";
import { MdRefresh } from "react-icons/md";
import { Tooltip } from "react-tooltip";
import "react-tooltip/dist/react-tooltip.css";

const cryptoData = [

  { img: eth, textOne: "ETH", textTwo: "Ethereum" },
  { img: usdt, textOne: "USDT", textTwo: "Tether USDT" },
  { img: btc, textOne: "BTC", textTwo: "Bitcoin" },
  { img: sol, textOne: "SOL", textTwo: "Solana" },
  { img: ltc, textOne: "LTC", textTwo: "Litecoin" },
  { img: car, textOne: "ADA", textTwo: "Cardano" },
];

function Transaction() {
  const [loading, setLoading] = useState(true);
  const [transactions, setTransactions] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedSymbol, setSelectedSymbol] = useState("");
  const [type, setType] = useState("deposit");
  const [totalPages, setTotalPages] = useState(0);
  const [limit, setLimit] = useState(10);
  const [status, setStatus] = useState("");
  const [fromDate, setFromDate] = useState("");
  const [toDate, setToDate] = useState("");
  const [showCalendar, setShowCalendar] = useState(false);
  const [totalItems, setTotalItems] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [moveStatus, setMoveStatus] = useState("");
  const [tableRefresh, setTableRefresh] = useState(false);
  const [resetPaginationToggle, setResetPaginationToggle] = useState(false);

  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: "selection",
    },
  ]);
  const calendarRef = useRef(null);

  const handleChange = (selectedOption) => {
    handleReset()
    setSelectedSymbol(selectedOption ? selectedOption.value : "");
  };

  const cryptoOptions = cryptoData.map((data) => ({
    value: data.textOne,
    label: (
      <div style={{ display: "flex", alignItems: "center" }}>
        <img
          src={data.img}
          alt={data.textOne}
          style={{ width: 20, height: 20, marginRight: 10 }}
        />
        {data.textOne}
      </div>
    ),
  }));


  useEffect(() => {
    const handleClickOutside = (event) => {
      if (calendarRef.current && !calendarRef.current.contains(event.target)) {
        setShowCalendar(false);
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handleDateChange = (item) => {
    setRange([item.selection]);

    const formatDate = (date) => {
      return date.toLocaleDateString("en-CA");
    };

    setFromDate(formatDate(item.selection.startDate));
    setToDate(formatDate(item.selection.endDate));
    setCurrentPage(1);
  };

  const formatWithoutRounding = (value, decimals) => {
    const factor = Math.pow(10, decimals);
    return Math.floor(value * factor) / factor;
  };

  const userpower = (x) => {
    x = x.toString();

    if (x.includes('e-')) {
      const [num, exp] = x.split('e-');
      const e = parseInt(exp);
      const digits = num.replace('.', '');
      const result = '0.' + '0'.repeat(e - 1) + digits;
      return result;
    } else if (x.includes('e+')) {
      const [num, exp] = x.split('e+');
      const e = parseInt(exp);
      const [intPart, decPart = ''] = num.split('.');
      let fullNum = intPart + decPart;
      while (fullNum.length < intPart.length + e) {
        fullNum += '0';
      }
      const decimal = fullNum.slice(0, intPart.length + e) + '.' + fullNum.slice(intPart.length + e);
      return decimal;
    }

    return x;
  }

  const getTransactionHistory = async (page = 1) => {
    try {
      let queryParams = new URLSearchParams({
        symbol: selectedSymbol || "",
        type: type || "",
        search: searchQuery || "",
        status: status || "",
        fromDate: fromDate || "",
        toDate: toDate || "",
        page: page,
        limit: limit,
        moveStatus: moveStatus || "",
      }).toString();
      let params = {
        url: `user-Transactionlist?${queryParams}`,
        method: "GET",
      };
      // console.log('params', params)
      let response = await makeApiRequest(params);
      // console.log('response', response)
      if (response.status === true) {
        setTransactions(response.data);
        setLoading(true);
        setTotalPages(response.totalPages);
        setTotalItems(response.totalItems);
      } else {
        setTransactions([]);
        setLoading(true);
        setTotalPages(0);
        setTotalItems(0);
      }
    } catch (error) {
      console.log("error", error);
      setLoading(true);
    } finally {
      setLoading(false);
    }
  };

  const handleClearFilters = async () => {
    setIsRefreshing(true); // Start spinning
    setSearchQuery("");
    setSelectedSymbol("");
    setStatus("");
    setFromDate("");
    setToDate("");
    setMoveStatus("")
    setShowCalendar("")
    setCurrentPage(1);
    setLimit(10);
    const start = Date.now();



    // getTransactionHistory(1);

    const elapsed = Date.now() - start;
    if (elapsed < 500) {
      // ensure at least 500ms rotation
      await new Promise(resolve => setTimeout(resolve, 500 - elapsed));
    }


    setIsRefreshing(false);
    setTableRefresh(tableRefresh == true ? false : true);
  };

  const handleCopy = (text) => {
    navigator.clipboard.writeText(text);
    toast.success("Transaction Id copied!");
  };

  const handleReset = async () => {
    setLimit(10);
    setCurrentPage(1);
    setResetPaginationToggle(!resetPaginationToggle);
  }

  useEffect(() => {
    getTransactionHistory(currentPage);
  }, [selectedSymbol, fromDate, toDate, type, currentPage, searchQuery, limit, status, moveStatus]);

  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
    handleReset()
  };



  const compressString = (str) => {
    if (!str) {
      return "";
    }
    return str.length > 10 ? `${str.slice(0, 6)}...${str.slice(-4)}` : str;
  };

  const dateFormat = (date) => {
    try {
      const orgDate = new Date(date).toUTCString();
      // console.log('orgDate', orgDate)
      const hours = new Date(date).getUTCHours();
      const amOrPm = hours >= 12 ? "PM" : "AM";
      const formattedDate = orgDate.split(",")[1].split("GMT")[0] + amOrPm;
      return formattedDate;
    } catch (e) {
      return "Invalid Date Format";
    }
  };

  const columns = [
    {
      name: "S.No",
      selector: (row, index) => (currentPage - 1) * limit + index + 1,
      sortable: true,
      width: "75px",
    },
    {
      name: "Email",
      selector: (row) => row.userData.email || "--",
      sortable: true,
      width: "250px",
    },
    { name: "Amount", selector: (row) => userpower(formatWithoutRounding(userpower(row.amount), 8)) || "--", sortable: true },
    {
      name: "Transaction ID",
      selector: (row) => {
        if (row.txnId) {
          let explorerUrl = "#";

          if (row.moveCur === "ETH" || row.moveCur === "USDT") {
            explorerUrl = `${config.ETH_url}/tx/${row.txnId}`;
          } else if (row.moveCur === "BTC") {
            explorerUrl = `${config.BTC_URL}/tx/${row.txnId}`;
          } else if (row.moveCur === "SOL") {
            explorerUrl = `https://solscan.io/tx/${row.txnId}?cluster=${config.SOL_URL}`;
          } else if (row.moveCur === "ADA") {
            explorerUrl = `${config.ADA_URL}${row.txnId}`;
          } else if (row.moveCur === "LTC") {
            explorerUrl = `${config.LTC_URL}/${row.txnId}`;
          }

          return (
            <div className="d-flex align-items-center">
              <a
                href={explorerUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="me-2 text-truncate"
              >
                {compressString(row.txnId) || "--"}
              </a>
              <FaRegCopy
                className="copy-icon"
                onClick={() => handleCopy(row.txnId)}
                style={{ cursor: "pointer" }}
              />
            </div>
          );
        }
        return "--";
      },
      sortable: true,
    },
    {
      name: "Currency",
      selector: (row) => row.moveCur || "--",
      sortable: true,
    },
    ...(type === "deposit"
      ? [
        {
          name: "AdminMove Status",
          selector: (row) =>
            row.adminMoveStatus === 1
              ? "Moved"
              : row.adminMoveStatus === 0
                ? "Not Moved"
                : "--",
          sortable: true,
          width: "200px",
        },
      ]
      : []),
    ...(type === "withdraw"
      ? [
        {
          name: "Fees",
          selector: (row) => row.fees ? userpower(formatWithoutRounding(userpower(row.fees), 8)) :  "--",
          sortable: true,
          width: "250px",
        },
      ]
      : []),
    ...(type === "withdraw"
      ? [
        {
          name: "Reason",
          minWidth: "120px",
          selector: (row, index) => {
            const hasReason = !!row?.reason;
            const tooltipId = hasReason ? `reason-tooltip-${index}` : null;
            return (
              <>
                <span
                  {...(hasReason && {
                    "data-tooltip-id": tooltipId,
                    "data-tooltip-content": row?.reason,
                  })}
                  style={{
                    display: "inline-block",
                    width: "110px",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    cursor: hasReason ? "pointer" : "default",
                  }}
                >
                  {row?.reason || "--"}
                </span>

                {hasReason && <Tooltip id={tooltipId} place="bottom"
                  style={{
                    width: "210px",
                    wordWrap: "break-word",
                    whiteSpace: "wrap",
                    opacity: "1 !important",
                    zIndex: "99"
                  }}
                />}
              </>
            )
          }
        },
      ]
      : []),
    // { name: "Status", selector: row => row.status || "--", sortable: true },
    {
      name: "Date",
      selector: (row) => dateFormat(row.createdDate) || "--",
      sortable: true,
      width: "200px",
    },
  ];

  const customStyles = {
    control: (base, state) => ({
      ...base,
      borderColor: state.isFocused ? "var(--color-1)" : "var(--color-1)",
      boxShadow: state.isFocused ? "0 0 0 1px var(--color-1)" : "none",
      borderRadius: "8px",
      fontSize: "13px",
      "&:hover": {
        borderColor: "var(--color-1)",
      },
      minWidth: "140px",
    }),
    menu: (base) => ({
      ...base,
      borderRadius: "8px",
      marginTop: 4,
    }),
    singleValue: (base) => ({
      ...base,
      color: "#000",
    }),
    option: (base, state) => ({
      ...base,
      backgroundColor: state.isSelected
        ? "var(--color-1)"
        : state.isFocused
          ? "#58f9b07c"
          : "white",
      color: state.isSelected ? "var(--theme-text-1)" : "black",
      ":active": {
        backgroundColor: "var(--color-1)",
      },
      cursor: "pointer",
      fontSize: "13px",
    }),
    menuPortal: (base) => ({
      ...base,
      zIndex: 9999,
    }),
  };
  return (
    <div className="App">
      <ToastContainer />
      <div className="container-fluid" >
        <div className=" text-dark">
          <div className="row">
            <div className="col-lg-12">
              <div className="py-3 justify-content-center d-flex justify-content-between">
                <h3 className="component-user text-center ms-lg-0">
                  Transaction History
                </h3>
              </div>
              <div className="d-flex align-items-end gap-3 flex-wrap">
                {/* <form className="d-flex gap-2"> */}
                <div className="mb-3">
                  <label for="email" className="form-label">
                    {" "}
                    Email, Transaction-ID
                  </label>
                  <input
                    type="text"
                    className="form-control search-bar"
                    name="email"
                    id="email"
                    aria-describedby="emailHelp"
                    placeholder="email, txid..."
                    value={searchQuery}
                    onChange={handleSearchChange}
                    style={{ width: "220px" }}
                  />
                </div>
                {/* </form> */}

                <div className="mb-3">
                  <label for="exampleInputPassword1" className="form-label">
                    Currency
                  </label>
                  <Select
                    options={cryptoOptions}
                    value={
                      selectedSymbol
                        ? cryptoOptions.find((option) => option.value === selectedSymbol)
                        : null
                    }
                    onChange={handleChange}
                    id="border-css"
                    isClearable
                    styles={customStyles}
                    isSearchable={false}
                    components={{
                      IndicatorSeparator: () => null,
                    }}
                  />
                </div>
                {type === "deposit" && (
                  <>
                    <div className="mb-3">
                      <label for="exampleInputPassword1" className="form-label">
                        Admin Move Status
                      </label>
                      <select
                        className="form-select search-bar"
                        aria-label="Default select example"
                        value={moveStatus}
                        onChange={(e) => { setMoveStatus(e.target.value); handleReset() }}
                      >
                        <option value="">Select Status</option>
                        <option value="1">Moved</option>
                        <option value="0">Not Moved</option>
                      </select>
                    </div>
                  </>
                )}
                <div className="mb-3">
                  <label for="exampleInputPassword1" className="form-label">
                    Date
                  </label>

                  {/* <div
                    ref={calendarRef}
                    style={{ position: "relative", width: "250px" }}
                  >
                    <div
                      onClick={() => setShowCalendar(!showCalendar)}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "space-between",
                        padding: "6px",
                        border: "1px solid #1eb7ff",
                        borderRadius: "5px",
                        cursor: "pointer",
                        backgroundColor: "#fff",
                        fontSize: "14px",
                      }}
                    >
                      <span>
                        {fromDate && toDate
                          ? `${fromDate} - ${toDate}`
                          : "Select Date Range"}
                      </span>
                      <FaCalendarAlt style={{ color: "#555" }} />
                    </div>
                    {showCalendar && (
                      <div
                        style={{
                          position: "absolute",
                          top: "100%",
                          left: -80,
                          zIndex: 1000,
                          background: "#fff",
                          boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                          borderRadius: "5px",
                        }}
                      >
                        <DateRange
                          editableDateInputs={true}
                          onChange={handleDateChange}
                          moveRangeOnFirstSelection={false}
                          ranges={range}
                          locale={enUS}
                          rangeColors={["rgb(137, 80, 218)"]}
                        />
                      </div>
                    )}
                  </div> */}

                  <div
                    ref={calendarRef}
                    style={{ position: "relative", width: "250px" }}
                  >
                    <div
                      onClick={() => { setShowCalendar(!showCalendar); handleReset() }}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "space-between",
                        padding: "6px",
                        border: "1px solid var(--color-1)",
                        borderRadius: "5px",
                        cursor: "pointer",
                        backgroundColor: "#fff",
                        fontSize: "14px",
                      }}
                    >
                      <span>
                        {fromDate && toDate ? `${fromDate} - ${toDate}` : "Select Date Range"}
                      </span>
                      <FaCalendarAlt style={{ color: "#555" }} />
                    </div>
                    {showCalendar && (
                      <div
                        style={{
                          position: "absolute",
                          top: "100%",
                          left: -80,
                          zIndex: 1000,
                          background: "#fff",
                          boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
                          borderRadius: "5px",
                        }}
                      >
                        <DateRange
                          editableDateInputs={true}
                          onChange={handleDateChange}
                          moveRangeOnFirstSelection={false}
                          ranges={range}
                          locale={enUS}
                          rangeColors={["#58f9b0"]}
                        />
                      </div>
                    )}
                  </div>

                </div>


                {type === "withdraw" && (
                  <>
                    <div className="mb-3 me-3">
                      <label htmlFor="status" className="form-label">
                        Withdraw Status
                      </label>
                      <select
                        className="form-select search-bar"
                        id="status"
                        value={status}
                        onChange={(e) => {
                          setStatus(e.target.value);
                          setCurrentPage(1);
                        }}
                      >
                        <option value="">All Status</option>
                        <option value="2">Approved</option>
                        <option value="1">Pending</option>
                        <option value="0">Rejected</option>
                      </select>
                    </div>
                  </>
                )}
                <div className="mb-2">
                  <button
                    type="button"
                    className="form-label custom-nav-button-1 active cursor-pointer"
                    onClick={handleClearFilters}
                    disabled={isRefreshing}
                  >
                    <MdRefresh
                      style={{ fontSize: "24px" }}
                      className={isRefreshing ? "rotate-icon" : ""}
                    />
                  </button>
                </div>
              </div>

              <div className="custom-inside-saled-order text-center mt-0  custom-nav-userlist-1">
                <ul
                  className="nav nav-pills mb-3 me-lg-0 text-center justify-content-lg-end align-items-center"
                  id="pills-tab"
                  role="tablist"
                >
                  <li></li>
                  <li className="nav-item" role="presentation">
                    <button
                      className={`nav-link register-btn-2 me-4  ${type === "deposit" ? "active" : ""
                        }`}
                      id="pills-home-tab"
                      onClick={() => { setType("deposit"); handleClearFilters() }}
                      type="button"
                      role="tab"
                      aria-selected={type === "deposit"}
                    >
                      Deposit
                    </button>
                  </li>
                  <li className="nav-item" role="presentation">
                    <button
                      className={`nav-link register-btn-2 ${type === "withdraw" ? "active" : ""
                        }`}
                      id="pills-profile-tab"
                      onClick={() => { setType("withdraw"); handleClearFilters() }}
                      type="button"
                      role="tab"
                      aria-selected={type === "withdraw"}
                    >
                      Withdraw
                    </button>
                  </li>
                </ul>
                <div
                  className="tab-content liquidity-table-1"
                  id="pills-tabContent"
                >
                  {/* {loading ? (
                    <div className="text-center">
                      <Spinner animation="border" />
                    </div>
                  ) : ( */}
                  <DataTable
                    key={tableRefresh}
                    columns={columns}
                    data={transactions}
                    theme="solarized"
                    defaultSortAsc={true}
                    pagination
                    paginationServer
                    persistTableHead
                    paginationPerPage={limit}
                    paginationTotalRows={totalItems}
                    paginationRowsPerPageOptions={[5, 10, 15]}
                    paginationResetDefaultPage={resetPaginationToggle}
                    onChangeRowsPerPage={(newRowsPerPage) => {
                      setLimit(newRowsPerPage);
                      setCurrentPage(1);
                    }}
                    onChangePage={(page) => setCurrentPage(page)}
                    highlightOnHover
                    dense
                    progressPending={loading}
                    progressComponent={
                      <div className="py-4 w-100 text-center">
                        <Spinner animation="border" />
                      </div>
                    }
                  />
                  {/* )} */}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Transaction;
